initial_sql:
SELECT T.Model FROM ( 
    SELECT ModelId, AVG(Weight) AS avg_weight FROM cars_data GROUP BY ModelId 
) AS T1 INNER JOIN car_names ON T1.ModelId = MakeId WHERE Weight < avg_weight

